SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "汉书·卷1下·高帝纪·葬长陵", "source_type": "primary", "author": "班固等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/hanshu-001-changling-burial/source.txt", "note": "《汉书》卷1下·高帝纪·葬长陵，段落 hanshu-d843e70ef156-p000245；已核上下文及传主，纸本及异文待核。", "id": "14eed9eb-e5d1-5c43-8fa2-f8755a18508a"}, {"title": "后汉书·卷2·显宗孝明帝纪·光武帝葬原陵", "source_type": "primary", "author": "范晔等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/houhanshu-002-yuanling-burial/source.txt", "note": "《后汉书》卷2·显宗孝明帝纪·光武帝葬原陵，段落 hou-hanshu-2d1104e7d6fe-p000543；已核上下文及传主，纸本及异文待核。", "id": "fefabb1b-d21e-5fcf-ad8d-ebf322f97cab"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年四月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/jiuwudaishi-103-april-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年四月，段落 jiu-wudaishi-205deb4a7860-p002486；已核上下文及传主，纸本及异文待核。", "id": "a4380470-0e2b-5159-8f88-ac1c4f501e80"}, {"title": "旧五代史·卷114·周世宗本纪·早年与贵州任职", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/jiuwudaishi-114-chai-rong-early/source.txt", "note": "《旧五代史》卷114·周世宗本纪·早年与贵州任职，段落 jiu-wudaishi-205deb4a7860-p002702；已核上下文及传主，纸本及异文待核。", "id": "d1f2275c-7904-5271-8c26-517704487918"}, {"title": "宋史·卷253·折德扆传·父子身份", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/songshi-253-zhe-deyi-family/source.txt", "note": "《宋史》卷253·折德扆传·父子身份，段落 songshi-9c6e46fee832-p057379；已核上下文及传主，纸本及异文待核。", "id": "9f28e86e-3823-5060-9403-29712fbdff5a"}, {"title": "资治通鉴·卷289·乾祐三年·四月、五月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/tongjian-289-950-spring-government/source.txt", "note": "《资治通鉴》卷289·乾祐三年·四月、五月及追述，段落 zizhi-tongjian-a63549944a71-p003428；已核上下文及传主，纸本及异文待核。", "id": "cb0261d9-f680-56de-aa8d-4f8732155971"}, {"title": "新五代史·卷12·周世宗本纪·早年与贵州任职", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/xinwudaishi-012-chai-rong-early/source.txt", "note": "《新五代史》卷12·周世宗本纪·早年与贵州任职，段落 xin-wudaishi-b08f244b9241-p000374；已核上下文及传主，纸本及异文待核。", "id": "ed082090-86ec-514f-84b7-cb4a5f922eac"}, {"title": "新五代史·卷20·周太祖圣穆皇后柴氏传", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/xinwudaishi-020-chai-empress/source.txt", "note": "《新五代史》卷20·周太祖圣穆皇后柴氏传，段落 xin-wudaishi-b08f244b9241-p000658；已核上下文及传主，纸本及异文待核。", "id": "7794935d-35b5-519c-96a6-de8733ee6144"}, {"title": "资治通鉴·卷289·乾祐三年·正月、二月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/aecd425b6a5c2b61245e92470190e94829f2d494/content/books/zizhi-tongjian/vol-289/year-0950/part-01/sources/library/tongjian-289-950-opening/source.txt", "note": "《资治通鉴》卷289·乾祐三年·正月、二月及追述，段落 zizhi-tongjian-a63549944a71-p003427；已核上下文及传主，纸本及异文待核。", "id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/77bbd325fb94c5e1dfb482972cb6de0b03c635d5/content/books/zizhi-tongjian/vol-289/year-0950/part-02/sources/library/jiuwudaishi-103-march-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年三月，段落 jiu-wudaishi-205deb4a7860-p002485；已核上下文及传主，纸本及异文待核。", "id": "ea95ea08-6ca9-55dc-8861-b133e12aa0b9"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "折从远", "aliases": ["折從遠", "折从阮", "折從阮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，府州刺史。后晋割让北地后，府州归属契丹。他据险抵制契丹迁民，后奉石重贵命令攻入契丹境内、拔十余寨，944年六月戊午任府州团练使。《新五代史》明确其后因避汉高祖名改称折从阮，字可久。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "500d7480-2e3a-5553-9370-8e4295db3cc1"}, {"name": "薛怀让", "aliases": ["薛懷讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋怀州刺史。944年二月乙巳与李守贞、皇甫遇、梁汉璋等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f1bb0fbd-9418-522b-b292-28446544ad7f"}, {"name": "杨承信", "aliases": ["楊承信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。《资治通鉴》称他为次子，938年五月与杨承祚同获优厚任官，具体官名未载。", "biography": null, "status": "draft", "id": "70bde002-fc6d-5293-9fb1-214458b656a6"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "王令温", "aliases": ["王令溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州河间人，后晋永清军节度使。免除邵珂军职，入朝时将其子邵崇范带在身边作人质。贝州陷落后家属被契丹俘获，944年正月被调为邓州节度使。生卒年本批未录。", "biography": null, "status": "draft", "id": "86d0426b-7115-5ca5-8f2c-358de92831a5"}, {"name": "王饶", "aliases": ["王饒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国左厢都指挥使。946年十月辛未，石重贵任命他为北征军的步军右厢都指挥使。《旧五代史》卷85记有相同部署。生卒年及籍贯未载。", "biography": null, "status": "draft", "id": "0da0dd37-babc-548d-b33d-f587847464ed"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "吴虔裕", "aliases": ["吳虔裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉河中行营都监。949年四月奉郭威之命，率兵从侧面攻击李守贞出城部队，击败对方并夺取攻城器具。生卒年尚未确定。", "biography": null, "status": "draft", "id": "e576a210-c5b6-5c62-8309-4f25ed7f2693"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "王章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州南乐人，曾任孔目官，随刘知远到太原。947年任权三司使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "154bd412-f052-5459-9c17-951cfcd91759"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "柴守礼", "aliases": ["柴守禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "柴荣的父亲，也是郭威妻子柴氏的兄长。《资治通鉴》和新旧五代史都记其父子身份；本段没有记其950年官职和生卒年。", "biography": null, "status": "draft", "id": "1f68967c-4559-5c4a-b49e-dda40ce4dd8e"}, {"name": "柴氏（郭威妻）", "aliases": ["圣穆皇后柴氏", "聖穆皇后柴氏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郭威的妻子，柴守礼的妹妹、柴荣的姑母。《新五代史》后妃传记她没有儿子，与郭威收养兄长之子柴荣，后称圣穆皇后。本段仅核亲属身份，不将后来皇后称号当作950年在位身份，生卒年尚未录入。", "biography": null, "status": "draft", "id": "9bcfb806-882b-5702-b418-26b2b55a3029"}, {"name": "折德扆", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "折从远（后名折从阮）之子，任府州蕃汉马步都指挥使。950年五月己亥获任府州团练使，《宋史》也明确记其父为从阮。生卒年未载。", "biography": null, "status": "draft", "id": "11515d9f-5a90-5398-9366-6f44b89ca847"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
