INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "后汉下诏在汉高祖、汉光武帝陵墓营建寝庙。", "citation": "卷289·乾祐三年（950年三月、四月、五月及追述）·zztj-v289-y0950-p013·原文件第18行", "note": "原文：甲寅，诏营寝庙于高祖长陵、世祖原陵，以时致祭。；核对说明：寝庙为陵墓祭祀建筑，所指两汉先帝，不能认作后汉刘知远陵墓。具体建筑规模和位置坐标未载。", "status": "draft", "id": "c9a7e43e-b772-54a1-a7f2-9351d9f5da38", "subject_id": "1bc9cec7-d8e3-59a1-90e6-82ee18125999", "source_id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年三月甲寅", "citation": "卷289·乾祐三年（950年三月、四月、五月及追述）·zztj-v289-y0950-p013·原文件第18行", "note": "原文：甲寅，诏营寝庙于高祖长陵、世祖原陵，以时致祭。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "514f22e6-f2a4-5ec0-b342-9091c64e2526", "subject_id": "1bc9cec7-d8e3-59a1-90e6-82ee18125999", "source_id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘承祐：下诏在两汉帝陵营建寝庙，按时祭祀。", "citation": "卷289·乾祐三年（950年三月、四月、五月及追述）·zztj-v289-y0950-p013·原文件第18行", "note": "原文：甲寅，诏营寝庙于高祖长陵、世祖原陵，以时致祭。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "c9a37c09-34f7-5fa5-9ea1-5ea7c945a22d", "subject_id": "96b54cac-772d-54e8-b2de-975b3be49e85", "source_id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘承祐：下诏在两汉帝陵营建寝庙，按时祭祀。", "citation": "卷289·乾祐三年（950年三月、四月、五月及追述）·zztj-v289-y0950-p013·原文件第18行", "note": "原文：甲寅，诏营寝庙于高祖长陵、世祖原陵，以时致祭。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "8cbd8f90-3a1a-5bf3-875b-123b547c1c19", "subject_id": "3435a68c-65a9-56f6-8623-b372683eec06", "source_id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"subject_table": "event", "field_path": "location_name", "claim_text": "《汉书》高帝纪记高帝葬在长陵，可用于识别本段汉高祖陵名。", "citation": "《汉书》卷1下·高帝纪·葬长陵，段落 hanshu-d843e70ef156-p000245；已核上下文及传主，纸本及异文待核。", "note": "原文：五月丙寅，葬長陵。；核对说明：只校核陵名，不将汉初下葬日期搬为950年，也不新建汉初丧葬事件。", "status": "draft", "id": "94ef3157-bfb1-525b-ac55-7427a0587139", "subject_id": "1bc9cec7-d8e3-59a1-90e6-82ee18125999", "source_id": "14eed9eb-e5d1-5c43-8fa2-f8755a18508a"}, {"subject_table": "event", "field_path": "location_name", "claim_text": "《后汉书》记光武皇帝葬原陵，并奉庙号世祖，可用于识别本段世祖原陵。", "citation": "《后汉书》卷2·显宗孝明帝纪·光武帝葬原陵，段落 hou-hanshu-2d1104e7d6fe-p000543；已核上下文及传主，纸本及异文待核。", "note": "原文：三月丁卯，葬光武皇帝於原陵。；核对说明：只校核陵主，不把古代下葬日当后汉诏令日期；原文注文中的地点不直接转为现代坐标。", "status": "draft", "id": "17c65152-cc54-5060-a336-e7b422eb1dba", "subject_id": "1bc9cec7-d8e3-59a1-90e6-82ee18125999", "source_id": "fefabb1b-d21e-5fcf-ad8d-ebf322f97cab"}, {"subject_table": "event", "field_path": "description", "claim_text": "主管官署认为费用过高，搁置帝陵寝庙计划。", "citation": "卷289·乾祐三年（950年三月、四月、五月及追述）·zztj-v289-y0950-p013·原文件第18行", "note": "原文：有司以费多，寝其事，；核对说明：寝其事解释为搁置计划，不写成已建成后停用；有司未具名。", "status": "draft", "id": "0e473b6c-bba4-5c61-a103-9bc43e84c64f", "subject_id": "8f3154cf-128c-50ae-91bd-b8391164b8c3", "source_id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年三月诏令之后，具体搁置日未载", "citation": "卷289·乾祐三年（950年三月、四月、五月及追述）·zztj-v289-y0950-p013·原文件第18行", "note": "原文：有司以费多，寝其事，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "924199c2-a21d-57ce-9e0a-df588c3c4aa3", "subject_id": "8f3154cf-128c-50ae-91bd-b8391164b8c3", "source_id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《资治通鉴》追记直到后汉灭亡，两陵也没有得到一次祭奠。", "citation": "卷289·乾祐三年（950年三月、四月、五月及追述）·zztj-v289-y0950-p013·原文件第18行", "note": "原文：以至国亡，二陵竟不沾一奠。；核对说明：这是跨时段结果概述，不能把后汉灭亡当作950年三月当天事件，未补后来全无祭祀的普遍结论。", "status": "draft", "id": "e490774d-c80a-5f4c-bb99-cdbdca9d0795", "subject_id": "8f3154cf-128c-50ae-91bd-b8391164b8c3", "source_id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"subject_table": "event", "field_path": "description", "claim_text": "高行周调任天平节度使。", "citation": "卷289·乾